 "content": "def transform(grid):
    # The grid is a lattice of 4x4 panels separated by full lines of 5.
    # The first panel in each band supplies that band's color; the patterned
    # panel in band 1, column 2 supplies a mask reproduced across every panel.
    sep = 5
    n = len(grid)
    starts = [i for i in range(n) if all(v == sep for v in grid[i])]
    row_bounds = [-1] + starts + [n]
    cols = len(grid[0])
    col_seps = [j for j in range(cols) if all(grid[i][j] == sep for i in range(n))]
    col_bounds = [-1] + col_seps + [cols]
    rh = [(row_bounds[k]+1, row_bounds[k+1]) for k in range(len(row_bounds)-1)]
    cw = [(col_bounds[k]+1, col_bounds[k+1]) for k in range(len(col_bounds)-1)]
    # Select the nonuniform pattern panel, excluding the swatch column.
    mask = None
    for ri, (r0, r1) in enumerate(rh):
        for ci, (c0, c1) in enumerate(cw):
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            colors = set(vals) - {0}
            if ci > 0 and len(colors) > 1:
                mask = [[grid[r][c] != 0 for c in range(c0, c1)] for r in range(r0, r1)]
                break
        if mask is not None:
            break
    if mask is None:
        # Fallback to the first nonempty nonswatch panel.
        for r0, r1 in rh:
            for c0, c1 in cw[1:]:
                if any(grid[r][c] != 0 for r in range(r0, r1) for c in range(c0, c1)):
                    mask = [[grid[r][c] != 0 for c in range(c0, c1)] for r in range(r1-1, r0-1, -1)]
                    break
            if mask is not None: break
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(rh):
        swatch = next((grid[r][c] for r in range(r0, r1) for c in range(cw[0][0], cw[0][1]) if grid[r][c] != 0), 0)
        for c0, c1 in cw[1:]:
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    out[r0+dr][c0+dc] = swatch if mask[dr][dc] else 0
    return out
