    h,w=len(grid),len(grid[0]); sep=5
    rb=[-1]+[i for i in range(h) if all(v==sep for v in grid[i])]+[h]
    cb=[-1]+[j for j in range(w) if all(grid[i][j]==sep for i in range(h))]+[w]
    rows=[(rb[k]+1,rb[k+1]) for k in range(len(rb)-1)]
    cols=[(cb[k]+1,cb[k+1]) for k in range(len(cb)-1)]
    panels=[]
    for ri,(r0,r1) in enumerate(rows):
        for ci,(c0,c1) in enumerate(cols):
            cells=[(r,c) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c] not in (0,sep)]
            panels.append((len(cells),ri,ci,r0,r1,c0,c1,cells))
    _,tri,tci,tr0,tr1,tc0,tc1,tcells=max(panels)
    mask=[[grid[tr0+dr][tc0+dc] not in (0,sep) for dc in range(tc1-tc0)] for dr in range(tr1-tr0)]
    out=[row[:] for row in grid]
    for ri,(r0,r1) in enumerate(rows):
        color=next((grid[r][c] for r in range(r0,r1) for c in range(cols[0][0],cols[0][1]) if grid[r][c] not in (0,sep)),0)
        for c0,c1 in cols:
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    out[r0+dr][c0+dc]=color if mask[dr][dc] else 0
    # Restore every separator cell exactly.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==sep: out[r][c]=sep
    return out
